---@class CVoicePackPkSender : CPidPacketSender
local CVoicePackPkSender = T(Global, "PidPacketSender")

function CVoicePackPkSender:sendPlayVoicePack(id)
    local player = PlayerManager:getClientPlayer()
    if not player.voicePackData then
        return
    end
    if not player.voicePackData:hasVoicePack(id) then
        return
    end
    player:sendPacket({
        pid = "PlayVoicePack",
        id = id,
    })
end